  'Comprehensive 30-day professional curriculum covering fundamentals, AI selections, high-end beauty retouching, vector typography, smart object packaging mockups, actions automation, and commercial print pre-press.',
  'Published',
  '[{"day": 1, "day_title": "Day 1: Interface, Color Modes & Canvas Architecture", "lessons": [{"sno": 1, "type": "lesson", "title": "Workspace Anatomy, Tools Panel & Scratch Disks", "duration": "90 mins", "format": "Interactive Lecture", "description": "Understanding raster graphics, PPI vs DPI, RGB vs CMYK color spaces, and optimizing performance with scratch disks.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day1-interface-guide.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Custom Workspace Setup & File Dimensions", "duration": "60 mins", "format": "Hands-on Lab", "description": "Create presets for Print (A4 300DPI), Web (1920x1080 72DPI), and Instagram Carousel formats with safety guides.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab1-canvas-presets.pdf"}]}, {"day": 2, "day_title": "Day 2: Geometric & Freehand Selection Workflows", "lessons": [{"sno": 1, "type": "lesson", "title": "Marquee Tools, Lasso, Polygonal & Magnetic Selections", "duration": "90 mins", "format": "Interactive Lecture", "description": "Selection mathematics: Add, Subtract, Intersect, Feathering, and Anti-Aliasing controls.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day2-selection-math.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Geometric Product Cutout & Isolation", "duration": "60 mins", "format": "Hands-on Lab", "description": "Isolate architectural objects and geometric packaging with pixel-perfect edges.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab2-cutouts.zip"}]}, {"day": 3, "day_title": "Day 3: AI-Powered Object Selection & Magic Wand", "lessons": [{"sno": 1, "type": "lesson", "title": "Object Selection Tool, Select Subject & Quick Selection", "duration": "90 mins", "format": "Interactive Lecture", "description": "Sensei AI subject boundary detection, tolerance thresholds, and contiguous pixel sampling.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day3-ai-selection.pdf"}, {"sno": 2, "type": "quiz", "title": "Quiz: Selection Tools & Edge Sensitivity", "duration": "30 mins", "format": "Online Assessment", "description": "10 questions on tolerance, sample all layers, and selection modifier shortcuts.", "status": "completed", "live_link": "", "doc_link": ""}]}, {"day": 4, "day_title": "Day 4: Select and Mask Workspace & Hair Extraction", "lessons": [{"sno": 1, "type": "lesson", "title": "Refine Edge Brush, Radius Tuning & Decontaminate Colors", "duration": "90 mins", "format": "Interactive Lecture", "description": "Extracting complex hair, animal fur, transparent smoke, and translucent glass without haloing.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day4-hair-refinement.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: High-Difficulty Portrait Extraction", "duration": "90 mins", "format": "Hands-on Lab", "description": "Extract a model with flying curly hair and place over contrasting solid backgrounds.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab4-portrait-assets.zip"}]}, {"day": 5, "day_title": "Day 5: Non-Destructive Layer Architecture & Groups", "lessons": [{"sno": 1, "type": "lesson", "title": "Layer Stacking, Opacity vs Fill & Color Coding", "duration": "90 mins", "format": "Interactive Lecture", "description": "Organizing complex enterprise PSD files with color-coded groups, layer filtering, and search.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day5-layers.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Commercial Banner PSD Organization", "duration": "60 mins", "format": "Hands-on Lab", "description": "Re-structure an unorganized 40-layer commercial file into standard design agency folders.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab5-unorganized.psd"}]}, {"day": 6, "day_title": "Day 6: Layer Masks, Clipping Masks & Transparency", "lessons": [{"sno": 1, "type": "lesson", "title": "The Power of Black, White & Grayscale Layer Masks", "duration": "90 mins", "format": "Interactive Lecture", "description": "Non-destructive masking workflows, clipping text layers, and creating shaped image frames.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day6-masking.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Double Exposure Creative Poster", "duration": "75 mins", "format": "Hands-on Lab", "description": "Combine portrait silhouette with a pine forest landscape using advanced gradient masks.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab6-double-exposure.zip"}]}, {"day": 7, "day_title": "Day 7: Weekly Capstone 1 – Surreal Photo Manipulation", "lessons": [{"sno": 1, "type": "task", "title": "Capstone Challenge: Fantasy Realm Composite", "duration": "120 mins", "format": "Creative Practicum", "description": "Combine 5 separate images (sky, mountain, temple, character, glowing orb) using selection and layer masks.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/capstone1-brief.pdf"}, {"sno": 2, "type": "test", "title": "Week 1 Review & Skill Evaluation", "duration": "45 mins", "format": "Online Assessment", "description": "Comprehensive review of selection mathematics, shortcuts, and masking theory.", "status": "completed", "live_link": "", "doc_link": ""}]}, {"day": 8, "day_title": "Day 8: Tonal Adjustments – Levels, Curves & Histograms", "lessons": [{"sno": 1, "type": "lesson", "title": "Reading the Histogram, Black Point, White Point & Midtones", "duration": "90 mins", "format": "Interactive Lecture", "description": "Mastering S-Curves, targeted channel adjustments (Red, Green, Blue), and dynamic range correction.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day8-curves.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Underexposed & Washed-out Image Restoration", "duration": "60 mins", "format": "Hands-on Lab", "description": "Fix extreme lighting scenarios using only Curves adjustment layers without clipping highlights.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab8-exposure-assets.zip"}]}, {"day": 9, "day_title": "Day 9: Color Grading, Hue/Saturation & Color Balance", "lessons": [{"sno": 1, "type": "lesson", "title": "Cinematic Color Grading & Selective Color Isolation", "duration": "90 mins", "format": "Interactive Lecture", "description": "Color theory in Photoshop: Complimentary split-toning (Teal & Orange), Vibrance vs Saturation, and Color Lookup tables (LUTs).", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day9-color-grading.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Hollywood Movie Look Color Grade", "duration": "60 mins", "format": "Hands-on Lab", "description": "Apply stylized cyberpunk and blockbuster cinematic grades to raw daytime urban photos.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab9-movie-look.zip"}]}, {"day": 10, "day_title": "Day 10: Retouching Essentials – Healing & Clone Stamp", "lessons": [{"sno": 1, "type": "lesson", "title": "Spot Healing, Healing Brush, Patch Tool & Clone Stamp", "duration": "90 mins", "format": "Interactive Lecture", "description": "Sampling sources, alignment, blending modes in cloning, and cleaning blemishes on blank layers.", "status": "completed", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day10-healing-tools.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Vintage Scratched Photo Restoration", "duration": "75 mins", "format": "Hands-on Lab", "description": "Restore a torn, dust-stained historical photograph from 1940 with seamless texture cloning.", "status": "completed", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab10-vintage-repair.zip"}]}, {"day": 11, "day_title": "Day 11: High-End Portrait Retouching & Frequency Separation", "lessons": [{"sno": 1, "type": "lesson", "title": "Frequency Separation: High Texture vs Low Color/Tone", "duration": "90 mins", "format": "Interactive Lecture", "description": "16-bit vs 8-bit Gaussian math, Apply Image equations, and smoothing skin tones without losing organic pores.", "status": "current", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day11-frequency-separation.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Commercial Beauty Portrait Editorial", "duration": "90 mins", "format": "Hands-on Lab", "description": "Perform full commercial retouch: Dodge & Burn skin contouring, iris brightening, and frequency separation.", "status": "current", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab11-beauty-portrait.zip"}]}, {"day": 12, "day_title": "Day 12: Content-Aware Fill & Object Removal", "lessons": [{"sno": 1, "type": "lesson", "title": "Content-Aware Workspace, Scale & Move Tools", "duration": "90 mins", "format": "Interactive Lecture", "description": "Customizing sample areas, perspective scaling, and removing large crowds from tourist landmarks.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day12-content-aware.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Removing Unwanted Objects & Crowd Clearing", "duration": "60 mins", "format": "Hands-on Lab", "description": "Clear power lines, pedestrians, and cars from a clean architectural photography scene.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab12-removal-assets.zip"}]}, {"day": 13, "day_title": "Day 13: Neural Filters & Adobe Firefly Generative AI", "lessons": [{"sno": 1, "type": "lesson", "title": "Generative Fill, Generative Expand & Neural Filters", "duration": "90 mins", "format": "Interactive Lecture", "description": "Prompt engineering in Photoshop, extending canvas boundaries, harmonizing lighting, and neural facial expression tuning.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day13-generative-ai.pdf"}, {"sno": 2, "type": "quiz", "title": "Quiz: Color, Tonal Science & Retouching Workflows", "duration": "30 mins", "format": "Online Assessment", "description": "15 questions covering Curves, Frequency Separation layers, and generative resolution specs.", "status": "upcoming", "live_link": "", "doc_link": ""}]}, {"day": 14, "day_title": "Day 14: Weekly Capstone 2 – High-Fashion Magazine Cover", "lessons": [{"sno": 1, "type": "task", "title": "Capstone Challenge: Vogue/GQ Editorial Cover Retouch", "duration": "120 mins", "format": "Creative Practicum", "description": "Complete high-end magazine cover with frequency separation, color grading, backdrop replacement, and typography.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/capstone2-brief.pdf"}, {"sno": 2, "type": "test", "title": "Mid-Term Practical Portfolio Critique", "duration": "60 mins", "format": "Practical Exam", "description": "Peer and faculty review of Week 2 retouched output files against commercial print standards.", "status": "upcoming", "live_link": "", "doc_link": ""}]}, {"day": 15, "day_title": "Day 15: Pen Tool Mastery, Vector Paths & Anchor Points", "lessons": [{"sno": 1, "type": "lesson", "title": "The Bézier Curve: Corner Points, Smooth Points & Handles", "duration": "90 mins", "format": "Interactive Lecture", "description": "Creating paths with sub-pixel precision, converting paths to selections, and mastering keyboard modifiers.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day15-pen-tool.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Vector Pen Tracing & Product Clipping Path", "duration": "75 mins", "format": "Hands-on Lab", "description": "Trace an automotive silhouette with smooth, seamless curves and export as an embedded clipping path.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab15-car-silhouette.zip"}]}, {"day": 16, "day_title": "Day 16: Shape Layers, Vector Masks & Custom Geometry", "lessons": [{"sno": 1, "type": "lesson", "title": "Custom Shapes, Boolean Operations & Vector Masks", "duration": "90 mins", "format": "Interactive Lecture", "description": "Combining shape layers: Unite, Subtract, Intersect, Exclude, and creating responsive UI components.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day16-shapes.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Vector Badges & Minimalist Icon Set", "duration": "60 mins", "format": "Hands-on Lab", "description": "Design an 8-piece corporate badge set exclusively with shape layers and vector masks.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab16-badges.pdf"}]}, {"day": 17, "day_title": "Day 17: Typography Design, Kerning & Text Effects", "lessons": [{"sno": 1, "type": "lesson", "title": "Character Panel, OpenType Ligatures, Kerning & Tracking", "duration": "90 mins", "format": "Interactive Lecture", "description": "Type hierarchy, paragraph styles, text on a path, converting type to shapes, and clipping images inside text.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day17-typography.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Event Poster Typographic Hierarchy", "duration": "60 mins", "format": "Hands-on Lab", "description": "Create a music festival poster balancing headline display typography, sponsor logos, and date details.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab17-festival.zip"}]}, {"day": 18, "day_title": "Day 18: Layer Styles & FX – Metallic, Glass & Neon", "lessons": [{"sno": 1, "type": "lesson", "title": "Deep Dive into Blending Options, Bevel & Emboss, Glows", "duration": "90 mins", "format": "Interactive Lecture", "description": "Contour curves in Bevel & Emboss, multi-layered Drop Shadows, Chrome/Gold metallic effects, and Cyberpunk Neon.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day18-layer-styles.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Chrome Metallic & Glowing Neon Text Logo", "duration": "60 mins", "format": "Hands-on Lab", "description": "Generate fully editable non-destructive layer style presets for 80s chrome and cyberpunk signage.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab18-styles.asl"}]}, {"day": 19, "day_title": "Day 19: The Brush Engine, Dynamics & Custom Presets", "lessons": [{"sno": 1, "type": "lesson", "title": "Shape Dynamics, Scattering, Dual Brush & Pen Pressure", "duration": "90 mins", "format": "Interactive Lecture", "description": "Configuring Wacom/iPad pressure sensitivity, creating custom stamp brushes from real smoke/water splash photos.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day19-brush-engine.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Creating a 10-Pack Cloud & Smoke Brush Library", "duration": "60 mins", "format": "Hands-on Lab", "description": "Photograph/isolate real organic textures and convert them into high-resolution reusable .ABR brush files.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab19-organic-textures.zip"}]}, {"day": 20, "day_title": "Day 20: Digital Matte Painting & Atmospheric Lighting", "lessons": [{"sno": 1, "type": "lesson", "title": "Volumetric God Rays, Fog, Rain, Snow & Depth Map Masks", "duration": "90 mins", "format": "Interactive Lecture", "description": "Atmospheric perspective rendering, painted light wraps, and blending foreground assets into landscape backplates.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day20-matte-painting.pdf"}, {"sno": 2, "type": "quiz", "title": "Quiz: Vectors, Typography & Lighting Physics", "duration": "30 mins", "format": "Online Assessment", "description": "15 questions on Bézier anchor points, contour curves, and atmospheric scattering rules.", "status": "upcoming", "live_link": "", "doc_link": ""}]}, {"day": 21, "day_title": "Day 21: Weekly Capstone 3 – Cinematic Movie Key Art", "lessons": [{"sno": 1, "type": "task", "title": "Capstone Challenge: Sci-Fi / Action Movie Poster", "duration": "150 mins", "format": "Creative Practicum", "description": "Produce 27x40 inch movie poster featuring character extraction, matte painted environment, billing block, and 3D title text.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/capstone3-movie-brief.pdf"}, {"sno": 2, "type": "test", "title": "Week 3 Peer Review & Typography Audit", "duration": "45 mins", "format": "Practical Exam", "description": "Evaluate kerning consistency, lighting direction accuracy, and layer style legibility.", "status": "upcoming", "live_link": "", "doc_link": ""}]}, {"day": 22, "day_title": "Day 22: Smart Objects, Linked Assets & Smart Filters", "lessons": [{"sno": 1, "type": "lesson", "title": "Embedded vs Linked Smart Objects & Filter Masks", "duration": "90 mins", "format": "Interactive Lecture", "description": "Why Smart Objects preserve raw sensor data, updating master assets across multiple documents, and stacking re-editable filters.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day22-smart-objects.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Non-Destructive Filter Pipeline", "duration": "60 mins", "format": "Hands-on Lab", "description": "Build a re-usable photo vintage texture stack using smart blur, smart sharpen, and grain filters.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab22-filters.zip"}]}, {"day": 23, "day_title": "Day 23: Camera Raw as a Smart Filter & Dynamic Range", "lessons": [{"sno": 1, "type": "lesson", "title": "Adobe Camera Raw (ACR) Inside Photoshop", "duration": "90 mins", "format": "Interactive Lecture", "description": "Clarity, Texture, Dehaze, Color Mixer, Masking with Luminance/Depth Ranges directly on smart layers.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day23-acr.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: High Dynamic Range Landscape Polish", "duration": "60 mins", "format": "Hands-on Lab", "description": "Recover crushed shadows and blown-out sunset clouds using ACR smart radial masks.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab23-raw-assets.dng"}]}, {"day": 24, "day_title": "Day 24: Warping Systems – Puppet Warp, Perspective & Liquify", "lessons": [{"sno": 1, "type": "lesson", "title": "Puppet Warp Pins, Perspective Planes & Face-Aware Liquify", "duration": "90 mins", "format": "Interactive Lecture", "description": "Repositioning character limbs with mesh density pins, fixing building perspective, and subtle cosmetic adjustments.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day24-warping.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Billboard Perspective Projection & Pose Modification", "duration": "60 mins", "format": "Hands-on Lab", "description": "Map flat artwork accurately onto an angled 2-point perspective times square billboard with realistic gloss.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab24-perspective.zip"}]}, {"day": 25, "day_title": "Day 25: Commercial Packaging & Product Mockup Creation", "lessons": [{"sno": 1, "type": "lesson", "title": "Creating Editable Client Mockups from Scratch", "duration": "90 mins", "format": "Interactive Lecture", "description": "Smart object distortion, displacement maps for fabric wrinkles, environmental reflections, and specular highlight layers.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day25-mockups.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Beverage Bottle & T-Shirt Smart Mockup", "duration": "90 mins", "format": "Hands-on Lab", "description": "Create a 1-click editable PSD mockup for an energy drink can with realistic condensation drops.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab25-mockup-blank.psd"}]}, {"day": 26, "day_title": "Day 26: Social Media Brand Kit & Carousel Architecture", "lessons": [{"sno": 1, "type": "lesson", "title": "Seamless Instagram Carousels & Artboards", "duration": "90 mins", "format": "Interactive Lecture", "description": "Artboard tool workflows, designing 1080x1350 multi-slide panoramic continuous carousels, and visual flow psychology.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day26-carousels.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: 5-Slide Seamless Educational Carousel", "duration": "75 mins", "format": "Hands-on Lab", "description": "Build a high-conversion 5-slide continuous carousel with elements bridging slide borders.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab26-carousel-template.psd"}]}, {"day": 27, "day_title": "Day 27: UI/UX Asset Preparation, Icon Slices & WebP Export", "lessons": [{"sno": 1, "type": "lesson", "title": "Export As Engine, 1x/2x/3x Retina Assets & SVG/WebP", "duration": "90 mins", "format": "Interactive Lecture", "description": "Preparing visual assets for modern frontend developers, lossless WebP compression, and color profiles for OLED displays.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day27-ui-export.pdf"}, {"sno": 2, "type": "quiz", "title": "Quiz: Smart Objects, Displacement & Web Export Specs", "duration": "30 mins", "format": "Online Assessment", "description": "15 questions on displacement map channels, artboard export options, and retina scaling.", "status": "upcoming", "live_link": "", "doc_link": ""}]}, {"day": 28, "day_title": "Day 28: Automation, Actions & Batch Processing Scripts", "lessons": [{"sno": 1, "type": "lesson", "title": "Recording Actions, Conditional Steps & Image Processor", "duration": "90 mins", "format": "Interactive Lecture", "description": "Automating repetitive studio tasks: Watermarking 500 product photos, resizing, and converting formats in seconds.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day28-actions.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Batch Watermark & Web Optimizer Action", "duration": "60 mins", "format": "Hands-on Lab", "description": "Record a robust custom Action that resizes any orientation photo to 2048px width, applies unsharp mask, and saves WebP.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab28-batch-samples.zip"}]}, {"day": 29, "day_title": "Day 29: Commercial Print Pre-Press vs Digital Web Standards", "lessons": [{"sno": 1, "type": "lesson", "title": "Bleed, Trim, Safe Zones, CMYK Proofing & PDF/X-1a", "duration": "90 mins", "format": "Interactive Lecture", "description": "Avoiding disastrous print errors: Total Area Coverage (TAC limit), Rich Black vs 100K Black, and soft-proofing ICC profiles.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-batch", "doc_link": "https://docs.bixcel.edu/photoshop/day29-prepress.pdf"}, {"sno": 2, "type": "task", "title": "Practical Lab: Print-Ready Tri-Fold Brochure Pre-Flight", "duration": "60 mins", "format": "Hands-on Lab", "description": "Pre-flight check a 300 DPI CMYK corporate brochure with 3mm bleed guides and zero RGB artifacts.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/lab29-brochure.psd"}]}, {"day": 30, "day_title": "Day 30: Final Comprehensive Capstone & Certification", "lessons": [{"sno": 1, "type": "test", "title": "Professional Adobe Photoshop Certification Exam", "duration": "90 mins", "format": "Practical Exam", "description": "Comprehensive theoretical and practical exam covering selections, retouching, color theory, and automation.", "status": "upcoming", "live_link": "https://meet.bixcel.edu/photoshop-exam", "doc_link": "https://docs.bixcel.edu/photoshop/final-exam-guidelines.pdf"}, {"sno": 2, "type": "task", "title": "Final Project: 360° Commercial Brand Campaign Showcase", "duration": "180 mins", "format": "Creative Practicum", "description": "Complete portfolio delivery: Retouched hero model visual, product packaging mockup, social media campaign, and billboard print pre-press file.", "status": "upcoming", "live_link": "", "doc_link": "https://docs.bixcel.edu/photoshop/final-capstone-brief.pdf"}]}]',
